 async function inspect(p:Point){setSelected({lon:p.lon,lat:p.lat});setEvidence(undefined);setInspectionBusy(true);const n=++serial.current;try{const e=await get(`/v1/evidence/at?lon=${p.lon}&lat=${p.lat}`);if(n===serial.current)setEvidence(e);}catch(e){setError((e as Error).message);}finally{if(n===serial.current)setInspectionBusy(false);}}
