   <nav className="workspace-tabs advanced-only"><button className={tab==='mission'?'active':''} onClick={()=>setTab('mission')}>01 <span>Expedition</span></button><button className={tab==='science'?'active':''} onClick={()=>setTab('science')}>02 <span>Science layers</span></button></nav>
